True from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {v: sum(row.count(v) for row in grid) for v in set(x for row in grid for x in row)}
    background = max(counts, key=counts.get)
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != background or (r, c) in seen:
                continue
            comp = []
            seen.add((r, c))
            q = deque([(r, c)])
            while q:
                x, y = q.popleft()
                comp.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == background and (nx, ny) not in seen:
                        seen.add((nx, ny))
                        q.append((nx, ny))
            components.append(comp)
    out = [row[:] for row in grid]
    for comp in components:
        rows = [r for r, c in comp]
        cols = [c for r, c in comp]
        r0, r1, c0, c1 = min(rows), max(rows), min(cols), max(cols)
        if len(comp) != (r1 - r0 + 1) * (c1 - c0 + 1):
            continue
        touched_sides = sum((r0 == 0, r1 == h - 1, c0 == 0, c1 == w - 1))
        if touched_sides <= 1:
            for r, c in comp:
                out[r][c] = 4
    return out
